/** Generated by DEXCORE: keeps a verified transfer alive with a progress notification. */
package com.jarves.mh.dexcoreupdate;

public final class DceArchiveUpdateService extends android.app.Service {
  public static final String EXTRA_TITLE = "dce_transfer_title";
  public static final String EXTRA_TEXT = "dce_transfer_text";
  public static final String EXTRA_PERCENT = "dce_transfer_percent";
  public static final int REQUEST_NOTIFICATIONS = 4211;
  private static final String CHANNEL_ID = "dce_archive_update_transfer";
  private static final int NOTIFICATION_ID = 4211;
  private static final long MIN_NOTIFICATION_INTERVAL_MS = 1000L;
  private static boolean active;
  private static int lastPercent = -2;
  private static long lastNotificationAt;
  private String title = "Update";
  private String text = "";
  private int percent = -1;

  /** Start (or refresh) the visible transfer. Call after the permission was granted. */
  public static synchronized void begin(android.content.Context context, String title, String text) {
    lastPercent = -2;
    lastNotificationAt = 0L;
    active = send(context, title, text, -1);
  }

  /** Mirror the real byte progress; the notification never invents a percentage. */
  public static synchronized void progress(android.content.Context context, String title, String text, int percent) {
    if (!active) return;
    long now = android.os.SystemClock.elapsedRealtime();
    // Byte callbacks arrive every 512 KiB. Coalesce service starts so progress
    // redraws cannot flood the main thread with binder/notification work.
    if (percent >= 0 && percent < 100 && now - lastNotificationAt < MIN_NOTIFICATION_INTERVAL_MS) return;
    if (percent == lastPercent && now - lastNotificationAt < 5L * MIN_NOTIFICATION_INTERVAL_MS) return;
    if (send(context, title, text, percent)) { lastPercent = percent; lastNotificationAt = now; }
    else active = false;
  }

  /** The transfer ended (installed, failed or unavailable): drop the notification. */
  public static synchronized void finish(android.content.Context context) {
    active = false;
    if (context == null) return;
    try { context.stopService(new android.content.Intent(context, DceArchiveUpdateService.class)); }
    catch (Exception ignored) { }
  }

  /** True when the notice may show progress notifications at all. */
  public static boolean permitted(android.content.Context context) {
    if (context == null) return false;
    if (android.os.Build.VERSION.SDK_INT < 33) return true;
    try { return context.checkSelfPermission("android.permission.POST_NOTIFICATIONS") == android.content.pm.PackageManager.PERMISSION_GRANTED; }
    catch (Exception unavailable) { return true; }
  }

  private static boolean send(android.content.Context context, String title, String text, int percent) {
    if (context == null) return false;
    try {
      android.content.Intent intent = new android.content.Intent(context, DceArchiveUpdateService.class);
      intent.putExtra(EXTRA_TITLE, title);
      intent.putExtra(EXTRA_TEXT, text);
      intent.putExtra(EXTRA_PERCENT, percent);
      if (android.os.Build.VERSION.SDK_INT >= 26) context.startForegroundService(intent);
      else context.startService(intent);
      return true;
    } catch (Exception ignored) { return false; }
  }

  @Override public int onStartCommand(android.content.Intent intent, int flags, int startId) {
    if (intent != null) {
      String nextTitle = intent.getStringExtra(EXTRA_TITLE);
      String nextText = intent.getStringExtra(EXTRA_TEXT);
      if (nextTitle != null && nextTitle.length() > 0) title = nextTitle;
      if (nextText != null) text = nextText;
      if (intent.hasExtra(EXTRA_PERCENT)) percent = intent.getIntExtra(EXTRA_PERCENT, percent);
    }
    // dataSync is declared in the manifest, so the type is passed on API 29+ where
    // Android requires it (and rejects a missing type from API 34).
    try {
      if (android.os.Build.VERSION.SDK_INT >= 29) {
        startForeground(NOTIFICATION_ID, notification(), android.content.pm.ServiceInfo.FOREGROUND_SERVICE_TYPE_DATA_SYNC);
      } else {
        startForeground(NOTIFICATION_ID, notification());
      }
    } catch (RuntimeException unavailable) {
      // A requested service whose foreground promotion was denied must stop;
      // otherwise Android can terminate the entire host on the FGS deadline.
      stopRetention();
      return START_NOT_STICKY;
    }
    // The app restarts or re-attaches a transfer; a killed one is never resumed blindly.
    return START_NOT_STICKY;
  }

  private void stopRetention() {
    synchronized (DceArchiveUpdateService.class) {
      active = false;
      lastPercent = -2;
      lastNotificationAt = 0L;
    }
    try { stopForeground(true); } catch (RuntimeException ignored) { }
    stopSelf();
  }

  // API 35+ dataSync has a platform time budget. Drop retention immediately
  // within the callback grace period; progress cannot restart an idle service.
  // This does not pretend that an ordinary process transfer is kill-proof.
  @Override public void onTimeout(int startId, int fgsType) {
    stopRetention();
  }

  private android.app.Notification notification() {
    if (android.os.Build.VERSION.SDK_INT >= 26) {
      android.app.NotificationManager manager = (android.app.NotificationManager) getSystemService(NOTIFICATION_SERVICE);
      if (manager != null && manager.getNotificationChannel(CHANNEL_ID) == null) {
        android.app.NotificationChannel channel = new android.app.NotificationChannel(
            CHANNEL_ID, title, android.app.NotificationManager.IMPORTANCE_LOW);
        channel.setShowBadge(false);
        manager.createNotificationChannel(channel);
      }
      return new android.app.Notification.Builder(this, CHANNEL_ID)
          .setContentTitle(title).setContentText(text)
          .setSmallIcon(android.R.drawable.stat_sys_download)
          .setOngoing(true).setOnlyAlertOnce(true)
          .setProgress(100, Math.max(0, percent), percent < 0).build();
    }
    return new android.app.Notification.Builder(this)
        .setContentTitle(title).setContentText(text)
        .setSmallIcon(android.R.drawable.stat_sys_download)
        .setOngoing(true).setOnlyAlertOnce(true)
        .setProgress(100, Math.max(0, percent), percent < 0).build();
  }

  @Override public android.os.IBinder onBind(android.content.Intent intent) { return null; }
}
